def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent color is the background.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Uniform non-background rows/columns are separators.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def make_segments(size, separators):
        segs, start = [], 0
        for p in separators:
            if start < p:
                segs.append((start, p))
            start = p + 1
        if start < size:
            segs.append((start, size))
        return segs

    rsegs = make_segments(h, sep_rows)
    csegs = make_segments(w, sep_cols)

    # Select the tile containing the most non-background cells.
    sr, sc = max(
        ((rs, cs) for rs in rsegs for cs in csegs),
        key=lambda pair: sum(
            grid[r][c] != bg
            for r in range(pair[0][0], pair[0][1])
            for c in range(pair[1][0], pair[1][1])
        )
    )
    tile_h, tile_w = sr[1] - sr[0], sc[1] - sc[0]

    out = [row[:] for row in grid]
    for r0, r1 in rsegs:
        for c0, c1 in csegs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    rr = sr[0] + (r - r0) % tile_h
                    cc = sc[0] + (c - c0) % tile_w
                    out[r][c] = grid[rr][cc]
    return out
